import { describe, expect, it } from "vitest";

import {
  applyAndroidAbis,
  applyReleaseSigning,
  applyShortCxxPath,
  type GradlePropertiesItem,
} from "./transforms.js";

// Excerpt of the android/app/build.gradle generated by `expo prebuild` (SDK 57).
const EXPO_BUILD_GRADLE = `
android {
    ndkVersion rootProject.ext.ndkVersion
    namespace 'com.example.app'
    signingConfigs {
        debug {
            storeFile file('debug.keystore')
            storePassword 'android'
            keyAlias 'androiddebugkey'
            keyPassword 'android'
        }
    }
    buildTypes {
        debug {
            signingConfig signingConfigs.debug
        }
        release {
            // Caution! In production, you need to generate your own keystore file.
            // see https://reactnative.dev/docs/signed-apk-android.
            signingConfig signingConfigs.debug
            def enableShrinkResources = findProperty('android.enableShrinkResourcesInReleaseBuilds') ?: 'false'
        }
    }
}
`;

describe("applyReleaseSigning", () => {
  it("signs the release with the upload key, read from prefixed Gradle properties", () => {
    const result = applyReleaseSigning(EXPO_BUILD_GRADLE, "MYAPP");

    expect(result).toMatch(
      /release \{[^}]*?\/\/ see [^\n]*\n\s*signingConfig signingConfigs\.release/,
    );
    expect(result).toContain(
      "storeFile file(findProperty('MYAPP_UPLOAD_STORE_FILE'))",
    );
    expect(result).toContain(
      "keyPassword findProperty('MYAPP_UPLOAD_KEY_PASSWORD')",
    );
  });

  it("keeps the debug key for the debug build only", () => {
    const result = applyReleaseSigning(EXPO_BUILD_GRADLE, "MYAPP");

    expect(result).toMatch(/debug \{\s*signingConfig signingConfigs\.debug/);
    expect(result.match(/signingConfig signingConfigs\.debug/g)).toHaveLength(
      1,
    );
  });

  it("leaves already-patched contents alone (prebuild run again)", () => {
    const once = applyReleaseSigning(EXPO_BUILD_GRADLE, "MYAPP");
    expect(applyReleaseSigning(once, "MYAPP")).toBe(once);
  });

  it("fails rather than leave the debug key when the template changed", () => {
    expect(() => applyReleaseSigning("android { }", "MYAPP")).toThrow(
      "signing block not found",
    );
  });

  it("requires an upper-case property prefix", () => {
    expect(() => applyReleaseSigning(EXPO_BUILD_GRADLE, undefined)).toThrow(
      "propertyPrefix",
    );
    expect(() => applyReleaseSigning(EXPO_BUILD_GRADLE, "my-app")).toThrow(
      "propertyPrefix",
    );
  });
});

describe("applyAndroidAbis", () => {
  it("adds ARM-only architectures by default", () => {
    const properties: GradlePropertiesItem[] = [
      { type: "comment", value: "reactNativeArchitectures" },
    ];
    expect(applyAndroidAbis(properties)).toEqual([
      { type: "comment", value: "reactNativeArchitectures" },
      {
        type: "property",
        key: "reactNativeArchitectures",
        value: "armeabi-v7a,arm64-v8a",
      },
    ]);
  });

  it("replaces an existing value, with custom ABIs", () => {
    const properties: GradlePropertiesItem[] = [
      {
        type: "property",
        key: "reactNativeArchitectures",
        value: "armeabi-v7a,arm64-v8a,x86,x86_64",
      },
    ];
    expect(applyAndroidAbis(properties, ["arm64-v8a"])).toEqual([
      { type: "property", key: "reactNativeArchitectures", value: "arm64-v8a" },
    ]);
  });
});

describe("applyShortCxxPath", () => {
  it("stages CMake builds in the given directory, with forward slashes", () => {
    const result = applyShortCxxPath(EXPO_BUILD_GRADLE, "D:\\cxx");
    expect(result).toContain('buildStagingDirectory "D:/cxx"');
    expect(result.indexOf("externalNativeBuild")).toBeLessThan(
      result.indexOf("namespace"),
    );
  });

  it("leaves already-patched contents alone", () => {
    const once = applyShortCxxPath(EXPO_BUILD_GRADLE, "C:/rncxx");
    expect(applyShortCxxPath(once, "C:/rncxx")).toBe(once);
  });

  it("fails when the namespace line is missing", () => {
    expect(() => applyShortCxxPath("android { }", "C:/rncxx")).toThrow(
      "namespace",
    );
  });
});
